import struct

def parse(frame: bytes):
    dst, src = frame[0:6].hex(":"), frame[6:12].hex(":")
    tpid = struct.unpack("!H", frame[12:14])[0]
    if tpid == 0x8100:
        tci, etype = struct.unpack("!HH", frame[14:18])
        return dict(dst=dst, src=src, pcp=tci >> 13, dei=(tci >> 12) & 1,
                    vid=tci & 0x0FFF, ethertype=hex(etype))
    return dict(dst=dst, src=src, vid=None, ethertype=hex(tpid))

f = bytes.fromhex("01005e000001" "020000000a01" "8100" "a00a" "0800") + b"\x00" * 46
print(parse(f))
